const data = msg.payload;

if (!data || typeof data !== "object") {
    node.warn("Pesan sensor bukan JSON object");
    return null;
}

data.received = new Date().toISOString();
flow.set("lastSensor", data);

const threshold = flow.get("temperatureThreshold");
const hasTemperature = data.suhu !== null && data.suhu !== undefined && data.suhu !== "" && Number.isFinite(Number(data.suhu));
const currentTemperature = hasTemperature ? Number(data.suhu) : NaN;
const previousTemperature = flow.get("previousTemperature");
const crossedThreshold = hasTemperature && currentTemperature > threshold &&
    (previousTemperature === undefined || previousTemperature <= threshold);

if (hasTemperature) {
    flow.set("previousTemperature", currentTemperature);
}

const databaseMessage = {
    topic: "INSERT INTO sensor_history (received, suhu, kelembaban, timestamp) VALUES ($received, $suhu, $kelembaban, $timestamp)",
    payload: [data.received, hasTemperature ? currentTemperature : null, data.kelembaban !== null && data.kelembaban !== undefined && Number.isFinite(Number(data.kelembaban)) ? Number(data.kelembaban) : null, data.timestamp || null]
};
const liveMessage = {
    payload: JSON.stringify({
        type: "sensor",
        data: data,
        alert: crossedThreshold ? {
            suhu: currentTemperature,
            threshold: threshold,
            received: data.received
        } : null
    })
};
let notificationMessage = null;

if (crossedThreshold) {
    notificationMessage = {
        topic: "iot/notifikasi",
        payload: [
            "PERINGATAN SUHU TINGGI",
            `Suhu: ${currentTemperature} C`,
            `Batas: ${threshold} C`,
            `Waktu (UTC): ${data.received}`
        ].join("\n")
    };
}

return [databaseMessage, liveMessage, notificationMessage, msg];

msg.topic = "CREATE TABLE IF NOT EXISTS sensor_history (id INTEGER PRIMARY KEY AUTOINCREMENT, received TEXT NOT NULL, suhu REAL, kelembaban REAL, timestamp TEXT)";
msg.payload = [];
return msg;

const expectedKey = env.get("IOT_API_KEY");
const suppliedKey = msg.req && msg.req.headers["x-api-key"];
msg.headers = {"Access-Control-Allow-Origin": "*"};

if (!expectedKey) {
    msg.statusCode = 503;
    msg.payload = {status: "error", message: "API key belum dikonfigurasi di Node-RED"};
    return msg;
}
if (!suppliedKey || suppliedKey !== expectedKey) {
    msg.statusCode = 401;
    msg.payload = {status: "error", message: "API key tidak ada atau salah"};
    return msg;
}

msg.statusCode = 200;
msg.payload = {
    status: "success",
    data: flow.get("lastSensor") || {suhu: null, kelembaban: null, timestamp: null},
    threshold: flow.get("temperatureThreshold"),
    server_time: new Date().toISOString()
};
return msg;

const expectedKey = env.get("IOT_API_KEY");
const suppliedKey = msg.req && msg.req.headers["x-api-key"];
msg.headers = {"Access-Control-Allow-Origin": "*"};

if (!expectedKey) {
    msg.statusCode = 503;
    msg.payload = {status: "error", message: "API key belum dikonfigurasi di Node-RED"};
    return [null, msg];
}
if (!suppliedKey || suppliedKey !== expectedKey) {
    msg.statusCode = 401;
    msg.payload = {status: "error", message: "API key tidak ada atau salah"};
    return [null, msg];
}

msg.topic = "SELECT id, received, suhu, kelembaban, timestamp FROM sensor_history ORDER BY id DESC LIMIT 50";
msg.payload = [];
return [msg, null];

const history = Array.isArray(msg.payload) ? msg.payload.reverse() : [];
msg.statusCode = 200;
msg.headers = {"Access-Control-Allow-Origin": "*"};
msg.payload = {status: "success", count: history.length, data: history};
return msg;

const expectedKey = env.get("IOT_API_KEY");
const suppliedKey = msg.req && msg.req.headers["x-api-key"];
msg.headers = {"Access-Control-Allow-Origin": "*"};

if (!expectedKey) {
    msg.statusCode = 503;
    msg.payload = {status: "error", message: "API key belum dikonfigurasi di Node-RED"};
    return [msg, null];
}
if (!suppliedKey || suppliedKey !== expectedKey) {
    msg.statusCode = 401;
    msg.payload = {status: "error", message: "API key tidak ada atau salah"};
    return [msg, null];
}

const body = msg.payload || {};
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: "error", message: "device dan action wajib diisi"};
    return [msg, null];
}

const mqttMessage = {topic: "iot/kontrol", payload: JSON.stringify(body)};
msg.statusCode = 200;
msg.payload = {status: "success", message: "Perintah terkirim", sent: body};
return [msg, mqttMessage];

const expectedKey = env.get("IOT_API_KEY");
const suppliedKey = msg.req && msg.req.headers["x-api-key"];
msg.headers = {"Access-Control-Allow-Origin": "*"};

if (!expectedKey) {
    msg.statusCode = 503;
    msg.payload = {status: "error", message: "API key belum dikonfigurasi di Node-RED"};
    return msg;
}
if (!suppliedKey || suppliedKey !== expectedKey) {
    msg.statusCode = 401;
    msg.payload = {status: "error", message: "API key tidak ada atau salah"};
    return msg;
}

const rawThreshold = msg.payload && msg.payload.threshold;
const threshold = Number(rawThreshold);
if (rawThreshold === null || rawThreshold === undefined || rawThreshold === "" || !Number.isFinite(threshold) || threshold < -50 || threshold > 200) {
    msg.statusCode = 400;
    msg.payload = {status: "error", message: "threshold harus berupa angka antara -50 dan 200 °C"};
    return msg;
}

flow.set("temperatureThreshold", threshold);
flow.set("previousTemperature", undefined);
msg.statusCode = 200;
msg.payload = {status: "success", message: "Batas suhu berhasil diperbarui", threshold: threshold};
return msg;

const errorMessage = msg.error && msg.error.message ? msg.error.message : "Kesalahan database";
if (!msg.req || !msg.res) {
    node.warn("SQLite error: " + errorMessage);
    return null;
}
msg.statusCode = 500;
msg.headers = {"Access-Control-Allow-Origin": "*"};
msg.payload = {status: "error", message: "Gagal membaca history dari database"};
return msg;
